-- Generated from official Data2/Patch/Comm/gamedata.csvZ Map_City_Coordniate (144 rows).
-- Map identity/world-map UI coordinate is official decoded data; coordinate bounds come from client navigation resources.
ALTER TABLE `god2_game`.`maps`
    ADD COLUMN IF NOT EXISTS `world_map_x` int NULL COMMENT 'Official world-map UI X; not a gameplay spawn',
    ADD COLUMN IF NOT EXISTS `world_map_y` int NULL COMMENT 'Official world-map UI Y; not a gameplay spawn',
    ADD UNIQUE KEY IF NOT EXISTS `ux_maps_client_identity` (`client_build_id`,`client_area_id`,`client_map_id`);

CREATE TABLE IF NOT EXISTS `god2_game`.`client_map_resource_identities` (
    `map_identity_id` bigint NOT NULL,
    `client_build_id` varchar(64) NOT NULL,
    `client_area_id` int NOT NULL,
    `client_map_id` int NOT NULL,
    `map_id` bigint NOT NULL,
    `resource_key` varchar(512) NOT NULL,
    `world_map_x` int NOT NULL,
    `world_map_y` int NOT NULL,
    `source_row` int NOT NULL,
    `source_sha256` char(64) NOT NULL,
    `identity_evidence_status` varchar(30) NOT NULL,
    `coordinate_evidence_status` varchar(30) NOT NULL,
    `enabled` tinyint(1) NOT NULL DEFAULT 0,
    PRIMARY KEY (`map_identity_id`),
    UNIQUE KEY `ux_client_map_resource_identity` (`client_build_id`,`client_area_id`,`client_map_id`),
    KEY `ix_client_map_resource_identity_resource` (`resource_key`),
    CONSTRAINT `fk_client_map_resource_identity_map` FOREIGN KEY (`map_id`) REFERENCES `god2_game`.`maps` (`map_id`),
    CONSTRAINT `fk_client_map_resource_identity_resource` FOREIGN KEY (`resource_key`) REFERENCES `god2_game`.`client_map_resources` (`resource_key`),
    CONSTRAINT `ck_client_map_resource_identity_enabled` CHECK (`enabled`=0 OR (`identity_evidence_status`='Verified' AND `coordinate_evidence_status` IN ('Verified','Derived')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

