ON DUPLICATE KEY UPDATE
    `map_id`=VALUES(`map_id`),`resource_key`=VALUES(`resource_key`),
    `world_map_x`=VALUES(`world_map_x`),`world_map_y`=VALUES(`world_map_y`),
    `source_row`=VALUES(`source_row`),`source_sha256`=VALUES(`source_sha256`),
    `identity_evidence_status`=VALUES(`identity_evidence_status`),`coordinate_evidence_status`=VALUES(`coordinate_evidence_status`),`enabled`=VALUES(`enabled`);

UPDATE `god2_game`.`client_map_resources` resource
JOIN (
    SELECT `resource_key`,MIN(`map_id`) AS `canonical_map_id`,MIN(`client_map_id`) AS `client_map_id`,
           MIN(`client_area_id`) AS `client_area_id`,MAX(`enabled`) AS `enabled`
    FROM `god2_game`.`client_map_resource_identities` GROUP BY `resource_key`
) identity_group ON identity_group.`resource_key`=resource.`resource_key`
SET resource.`canonical_map_id`=identity_group.`canonical_map_id`,resource.`client_map_id`=identity_group.`client_map_id`,resource.`client_area_id`=identity_group.`client_area_id`,
    resource.`map_identity_evidence_status`='Verified',resource.`enabled`=identity_group.`enabled`,
    resource.`admin_note`='Official gamedata identity joined to client navigation resource; Migration 114.'
WHERE resource.`client_build_id`='god2-opt-6b127086e0c0';

